let seed = Math.random() * 9999;
let num = 2;
let radius, mySize;
let v_planet = [];
let trails = [];
let t = 0;
let colors = [];
let bgColor;

function setup() {
	randomSeed(seed);
	// noiseSeed(seed);
	createCanvas(windowWidth, windowHeight, WEBGL);
	angleMode(RADIANS);
	mySize = max(windowWidth, windowHeight);
	radius = mySize * 0.35;

	colors = random(colorScheme).colors;
	colorbg = random(bgcolor)
	background(colorbg);

	for (let i = 0; i < num; i++) {
		trails.push([]);
	}
}

function draw() {
	randomSeed(seed);
	background(colorbg);

	let layerCount = 4;
	let R = radius * 0.35;

	// 更新行星轨迹
	for (let i = 0; i < num; i++) {
		let layer = i % layerCount;
		let layerAngleOffset = (TWO_PI / layerCount) * layer;
		let baseAngle = (TWO_PI / num) * i + t * 1.5;

		let spiralRadius = R * (1.4 + 1.5 * sin(t + i));
		let heightOffset = sin(t * 1.7 + i) * radius * 0.5;

		let theta = baseAngle + layerAngleOffset;
		let phi = t + i * 10.1;

		let x = spiralRadius * sin(theta) * cos(phi);
		let y = spiralRadius * sin(theta) * sin(phi);
		let z = spiralRadius * cos(theta) + heightOffset;

		let p = createVector(x, y, z);
		v_planet[i] = p;
		trails[i].push(p.copy());

		if (trails[i].length > 200) trails[i].shift();
	}

	// 绘制轨迹
	for (let i = 0; i < num; i++) {
		randomSeed(seed);

		push();
		rotateX(random(TAU) + frameCount / 100);
		rotateY(random(TAU) + frameCount / 100);
		rotateZ(random(TAU) + frameCount / 100);

		for (let j = 1; j < trails[i].length; j++) {
			// rotateX(j/10000);
			// rotateY(j/10000);
			// rotateZ(j/10000);
			let p1 = trails[i][j - 1];
			let p2 = trails[i][j];

			let progress = j / trails[i].length;
			if (progress > 0.75 && random() < 0.85) continue; // 模拟干笔断墨

			let baseSW = sin(progress * PI) * (i + 1) * 10;

			// 颜色
			let c = color(colors[i % colors.length]);
			let alpha = map(progress, 0, 1, 255, 255);
			c.setAlpha(alpha);

			// 抖动轨迹
			let p1_main = noiseJitterVec(p1, 1.0, frameCount / 1);
			let p2_main = noiseJitterVec(p2, 2.0, frameCount / 1);

			// 根据速度调节线宽
			let vel = p5.Vector.sub(p2_main, p1_main).mag();
			let dynamicSW = baseSW * map(vel, 0, 10, 0.1, 4.0);

			// 主线
			stroke(c);
			strokeWeight(dynamicSW);
			line(p1_main.x, p1_main.y, p1_main.z, p2_main.x, p2_main.y, p2_main.z);

			// 墨迹尾影线（淡细）
			let c3 = color(c);
			c3.setAlpha(alpha * 0.99);
			stroke(c3);
			strokeWeight(dynamicSW * 0.15);
			let offset = p5.Vector.random3D().mult(1);
			let p1_fade = p1_main.copy().add(offset);
			let p2_fade = p2_main.copy().add(offset);

			line(p1_fade.x, p1_fade.y, p1_fade.z, p2_fade.x, p2_fade.y, p2_fade.z);
		}
		pop();
	}

	// 画行星小球
	for (let i = 0; i < num; i++) {
		randomSeed(seed);

		push();
		rotateX(-random(TAU) + frameCount / 100);
		rotateY(-random(TAU) + frameCount / 100);
		rotateZ(-random(TAU) + frameCount / 100);
		var c = color(colors[i % colors.length]);
		c.setAlpha(255);
		fill(c);
		noStroke();
		translate(v_planet[i].x, v_planet[i].y, v_planet[i].z);
		sphere((i + 1) * 10);
		pop();
	}

	t += 0.1 / 10;
}

function noiseJitterVec(v, scale = 12, frame = 0) {
	randomSeed(seed);

	let n1 = noise(v.x * 0.005, v.y * 0.005, frame * 0.002);
	let n2 = noise(v.y * 0.005, v.z * 0.005, frame * 0.002);
	let n3 = noise(v.z * 0.005, v.x * 0.005, frame * 0.002);

	let jx = v.x + map(n1, 0, 1, -scale, scale);
	let jy = v.y + map(n2, 0, 1, -scale, scale);
	let jz = v.z + map(n3, 0, 1, -scale, scale);
	return createVector(jx, jy, jz);
}

